package com.bank.sensitivity;

import java.math.BigDecimal;
import java.util.Arrays;
import java.util.logging.Logger;

// Leave-one-out factor products for National Bank of India portfolio analytics.
public class SensitivityAnalyzer {
    private static final Logger log = Logger.getLogger(SensitivityAnalyzer.class.getName());

    // For each i, product of all factors except factors[i]. No division. O(n).
    public BigDecimal[] productExceptSelf(BigDecimal[] factors) {
        if (factors == null || factors.length == 0) {
            return new BigDecimal[0];
        }
        int n = factors.length;
        BigDecimal[] out = new BigDecimal[n];

        // Pass 1: left→right, out[i] = product of everything BEFORE i.
        BigDecimal prefix = BigDecimal.ONE;
        for (int i = 0; i < n; i++) {
            out[i] = prefix;                      // product before i
            prefix = prefix.multiply(factors[i]); // extend for next i
        }

        // Pass 2: right→left, multiply in product of everything AFTER i.
        BigDecimal suffix = BigDecimal.ONE;
        for (int i = n - 1; i >= 0; i--) {
            out[i] = out[i].multiply(suffix);     // prefix × suffix
            suffix = suffix.multiply(factors[i]); // extend for next i
        }
        log.info(() -> "Leave-one-out products: " + Arrays.toString(out));
        return out;
    }
}
