package com.bank.sensitivity;

import java.math.BigDecimal;
import java.util.Arrays;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: leave-one-out sensitivity on Rajesh's factor multipliers.
public class SensitivityDemo {
    private static final Logger log = Logger.getLogger(SensitivityDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    private static BigDecimal bd(String s) { return new BigDecimal(s); }

    public static void main(String[] args) {
        SensitivityAnalyzer analyzer = new SensitivityAnalyzer();

        // Rajesh (SAV2001) portfolio factor multipliers.
        BigDecimal[] factors = { bd("2"), bd("3"), bd("4"), bd("5") };
        BigDecimal[] result = analyzer.productExceptSelf(factors);
        log.info(() -> "Normal factors " + Arrays.toString(factors)
                + " → " + Arrays.toString(result));

        // Stress scenario: one factor is zero.
        BigDecimal[] stressed = { bd("2"), bd("0"), bd("4"), bd("5") };
        BigDecimal[] stressResult = analyzer.productExceptSelf(stressed);
        log.info(() -> "Stressed factors " + Arrays.toString(stressed)
                + " → " + Arrays.toString(stressResult));
    }
}
